"""VFDT / Hoeffding Tree learner for data streams.

Implements the classic Hoeffding Tree algorithm (Domingos & Hulten, 2000):
instances are sorted to leaves, statistics are accumulated in per-attribute
numeric observers, and a leaf is split once the Hoeffding bound guarantees
(with confidence 1 - delta) that the chosen attribute is the best split.
"""

import math
from typing import Dict, List, Optional, Tuple

from streams import Instance
from classifiers import AbstractClassifier, compute_hoeffding_bound
from attribute_observers import NumericAttributeObserver


class HoeffdingTreeLeaf:
    """Leaf node of a Hoeffding tree.

    Tracks per-class counts and one NumericAttributeObserver per attribute.
    Split candidates are evaluated every `grace_period` observed examples.
    """

    def __init__(self, num_classes: int, num_attributes: int, depth: int = 0,
                 num_bins: int = 10):
        self.num_classes = num_classes
        self.num_attributes = num_attributes
        self.depth = depth
        self.class_counts: List[float] = [0.0] * num_classes
        self.observers: List[NumericAttributeObserver] = [
            NumericAttributeObserver(num_bins=num_bins)
            for _ in range(num_attributes)
        ]
        self.examples_since_split = 0
        self.total_examples = 0

    def observe(self, instance: Instance, weight: float = 1.0):
        """Update class counts and attribute observers with one instance."""
        label = instance.label
        if 0 <= label < self.num_classes:
            self.class_counts[label] += weight
        for idx, observer in enumerate(self.observers):
            observer.observe(instance.features[idx], label, weight)
        self.examples_since_split += 1
        self.total_examples += 1

    def majority_class(self) -> int:
        """Return the class with the highest count (0 if no stats)."""
        best_class = 0
        best_count = 0.0
        for cls, count in enumerate(self.class_counts):
            if count > best_count:
                best_count = count
                best_class = cls
        return best_class

    def get_votes(self) -> Dict[int, float]:
        """Return the normalized class distribution at this leaf."""
        total = sum(self.class_counts)
        if total <= 0:
            uniform = 1.0 / self.num_classes if self.num_classes > 0 else 0.0
            return {cls: uniform for cls in range(self.num_classes)}
        return {cls: count / total for cls, count in enumerate(self.class_counts)}

    def get_split_suggestions(self) -> List[Tuple[float, int, float]]:
        """Evaluate all attributes, returning (info_gain, attr_idx, split_value)."""
        suggestions = []
        for attr_idx, observer in enumerate(self.observers):
            gain, split_value, _ = observer.get_best_split_suggestion(self.num_classes)
            suggestions.append((gain, attr_idx, split_value))
        return suggestions


class HoeffdingTreeSplit:
    """Internal node: binary numeric split (`< split_value` goes left)."""

    def __init__(self, split_attribute: int, split_value: float,
                 left, right, depth: int = 0):
        self.split_attribute = split_attribute
        self.split_value = split_value
        self.left = left
        self.right = right
        self.depth = depth

    def child_for(self, instance: Instance):
        if instance.features[self.split_attribute] < self.split_value:
            return self.left
        return self.right


class HoeffdingTree(AbstractClassifier):
    """Hoeffding Tree (VFDT) classifier.

    Splits a leaf when the information gain of the best attribute exceeds
    the second-best by more than the Hoeffding bound epsilon, or when
    epsilon falls below the tie threshold.
    """

    def __init__(self, grace_period: int = 200, split_confidence: float = 1e-7,
                 tie_threshold: float = 0.05, max_depth: int = 20,
                 num_classes: int = 2, num_attributes: Optional[int] = None):
        super().__init__()
        self.grace_period = grace_period
        self.split_confidence = split_confidence
        self.tie_threshold = tie_threshold
        self.max_depth = max_depth
        self.num_classes = num_classes
        self.num_attributes = num_attributes
        self.root: Optional[object] = None
        self._range_val = max(math.log2(max(num_classes, 2)), 1.0)

    def _new_leaf(self, depth: int) -> HoeffdingTreeLeaf:
        return HoeffdingTreeLeaf(self.num_classes, self.num_attributes, depth)

    def _sort_to_leaf(self, instance: Instance) -> HoeffdingTreeLeaf:
        node = self.root
        while isinstance(node, HoeffdingTreeSplit):
            node = node.child_for(instance)
        return node

    def train(self, instance: Instance):
        """Sort the instance to a leaf, update stats, maybe attempt a split."""
        if self.num_attributes is None:
            self.num_attributes = instance.num_attributes
        if self.root is None:
            self.root = self._new_leaf(depth=0)
        self.instances_seen += 1

        leaf = self._sort_to_leaf(instance)
        leaf.observe(instance)

        if (leaf.examples_since_split >= self.grace_period
                and leaf.depth < self.max_depth):
            leaf.examples_since_split = 0
            self._attempt_split(leaf, instance)

    def _attempt_split(self, leaf: HoeffdingTreeLeaf, instance: Instance):
        """Evaluate split candidates at a leaf and split if justified."""
        suggestions = leaf.get_split_suggestions()
        # Rank by gain, descending.
        suggestions.sort(key=lambda s: s[0], reverse=True)
        best_gain, best_attr, best_value = suggestions[0]
        second_gain = suggestions[1][0] if len(suggestions) > 1 else 0.0

        if best_gain <= 0.0:
            return  # no attribute has a real suggestion

        epsilon = compute_hoeffding_bound(
            self._range_val, self.split_confidence, leaf.total_examples)

        if (best_gain - second_gain > epsilon) or (epsilon < self.tie_threshold):
            self._split_leaf(leaf, instance, best_attr, best_value)

    def _split_leaf(self, leaf: HoeffdingTreeLeaf, instance: Instance,
                    split_attribute: int, split_value: float):
        """Replace `leaf` in the tree with a split node and two fresh leaves."""
        new_split = HoeffdingTreeSplit(
            split_attribute=split_attribute,
            split_value=split_value,
            left=self._new_leaf(depth=leaf.depth + 1),
            right=self._new_leaf(depth=leaf.depth + 1),
            depth=leaf.depth,
        )
        if self.root is leaf:
            self.root = new_split
        else:
            self._replace_child(self.root, leaf, new_split)

    def _replace_child(self, node: HoeffdingTreeSplit, old, new) -> bool:
        """Find the parent of `old` and swap in `new`."""
        while isinstance(node, HoeffdingTreeSplit):
            if node.left is old:
                node.left = new
                return True
            if node.right is old:
                node.right = new
                return True
            # Descend using structural identity: both subtrees are searched.
            if self._replace_child(node.left, old, new):
                return True
            if self._replace_child(node.right, old, new):
                return True
            return False
        return False

    def predict(self, instance: Instance) -> int:
        """Traverse to a leaf and return its majority class."""
        if self.root is None:
            return 0
        leaf = self._sort_to_leaf(instance)
        if leaf is None:
            return 0
        return leaf.majority_class()

    def get_votes(self, instance: Instance) -> Dict[int, float]:
        """Return the normalized class distribution at the instance's leaf."""
        if self.root is None:
            if self.num_classes <= 0:
                return {}
            uniform = 1.0 / self.num_classes
            return {cls: uniform for cls in range(self.num_classes)}
        leaf = self._sort_to_leaf(instance)
        if leaf is None:
            return {}
        return leaf.get_votes()

    def get_tree_size(self) -> Dict[str, int]:
        """Return node counts: num_leaves, num_splits, total_nodes."""
        num_leaves = 0
        num_splits = 0
        stack = [self.root]
        while stack:
            node = stack.pop()
            if node is None:
                continue
            if isinstance(node, HoeffdingTreeSplit):
                num_splits += 1
                stack.append(node.left)
                stack.append(node.right)
            else:
                num_leaves += 1
        return {
            "num_leaves": num_leaves,
            "num_splits": num_splits,
            "total_nodes": num_leaves + num_splits,
        }

